static inline const uint8_t* moodFrame(uint8_t which, uint16_t n) {
  if (which >= MOOD_GIF_COUNT) which = 0;
  uint16_t cnt = pgm_read_word(&MOOD_FRAME_COUNTS[which]);
  if (n >= cnt) n = 0;
  uint32_t off = pgm_read_dword(&MOOD_FRAME_OFFSETS[which]);
  return (const uint8_t*)MOOD_FRAMES + off + (uint32_t)n * MOOD_FRAME_BYTES;
}

